mapper.select:
SELECT tu.user_id AS userId, t.tenant_id AS tenantId, t.tenant_name AS tenantName, t.tenant_type AS tenantType FROM tenant_user tu INNER JOIN tenant t ON t.tenant_id = tu.tenant_id WHERE tu.user_id IN
#{userId}
AND tu.status = 1 AND tu.valid = 1 AND t.status = 1 AND t.valid = 1 ORDER BY tu.id
